// Explicit virtual host protocol: the controller only returns firmware bytes.
export async function enumerateSTMUSB(command,log=()=>{}){
 const reset=await command('reset');if(reset.status!=='ACK')throw Error('USB bağlı değil. USB firmware’ini derleyip başlatın.');
 const setup=async q=>{const p=await command('setup',{address:0,endpoint:0,data:q});if(p.status!=='ACK')throw Error('SETUP '+p.status);};
 const input=async(address,endpoint=0)=>{for(let n=0;n<20;n++){const p=await command('in',{address,endpoint});if(p.status!=='NAK')return p;}throw Error('USB yanıt zaman aşımı (NAK).');};
 const data=async n=>{await setup([128,6,0,1,0,0,n,0]);const p=await input(0);if(p.status!=='ACK'||p.data.length!==n)throw Error('Device descriptor geçersiz: '+p.status);await command('out',{address:0,endpoint:0,data:[]});return p.data;};
 await data(8);const descriptor=await data(18);if(descriptor[0]!==18||descriptor[1]!==1||descriptor[7]!==64)throw Error('Yalnız 64 bayt EP0 FS vendor örneği desteklenir.');log('DEVICE '+hex(descriptor));
 await setup([128,6,0,2,0,0,9,0]);const head=await input(0);if(head.status!=='ACK'||head.data.length!==9)throw Error('Configuration başlığı eksik.');await command('out',{address:0,endpoint:0,data:[]});const length=head.data[2]|head.data[3]<<8;if(length<9||length>64)throw Error('Sanal host tek paket configuration (9..64 bayt) destekler.');await setup([128,6,0,2,0,0,length,0]);const config=await input(0);if(config.status!=='ACK'||config.data.length!==length)throw Error('Configuration descriptor eksik.');log('CONFIG '+hex(config.data));await command('out',{address:0,endpoint:0,data:[]});
 await setup([0,5,7,0,0,0,0,0]);let p=await input(0);if(p.status!=='ACK'||p.data.length)throw Error('SET_ADDRESS status aşaması başarısız.');
 p=await command('setup',{address:7,endpoint:0,data:[0,9,1,0,0,0,0,0]});if(p.status!=='ACK')throw Error('SET_CONFIGURATION '+p.status);p=await input(7);if(p.status!=='ACK'||p.data.length)throw Error('SET_CONFIGURATION status aşaması başarısız.');log('Adres 7 · Configuration 1 · EP1 bulk hazır');return {address:7,descriptor,config:config.data};
}
const hex=bytes=>bytes.map(n=>n.toString(16).padStart(2,'0')).join(' ').toUpperCase();
export function showSTMUSBHost({showDialog,send}){
 showDialog('STM32 · Sanal USB host','<p>USB FS vendor cihazı · F103 PMA / IRQ20 veya F401/F411 OTG FIFO / IRQ67. Önce USB örneğini derleyip başlatın. PC’nin fiziksel USB aygıtlarına bağlanmaz.</p><div class="dialog-actions"><button id="usb-enumerate" class="primary">USB reset + aygıtı tanı</button></div><label style="display:block">EP1 bulk verisi<input style="display:block;width:100%;box-sizing:border-box;margin-top:6px" id="usb-payload" value="Wirevo USB" maxlength="256"></label><div class="dialog-actions"><button id="usb-echo" disabled>Bulk OUT → IN</button></div><hr><p>MCU host firmware’i için: sanal vendor echo aygıtını USB host kanalına bağlayın. USB host yalnız F401/F411’de bulunur.</p><div class="dialog-actions"><button id="usb-peer-attach">Sanal USB aygıtı bağla</button><button id="usb-peer-detach">Sanal aygıtı çıkar</button></div><p id="usb-state" role="status">Hazır firmware bekleniyor.</p><pre id="usb-log" class="json-preview" style="max-height:300px"></pre>');
 let address=0;const el=id=>document.getElementById(id),log=t=>{if(el('usb-log'))el('usb-log').textContent+=t+'\n';},busy=value=>{if(el('usb-enumerate'))el('usb-enumerate').disabled=value;if(el('usb-echo'))el('usb-echo').disabled=value||!address;};
 for(const [id,op]of [['usb-peer-attach','attach'],['usb-peer-detach','detach']])el(id).onclick=async()=>{try{const p=await send(op);el('usb-state').textContent=p.status;}catch(e){el('usb-state').textContent=e.message;}};
 el('usb-enumerate').onclick=async()=>{address=0;busy(true);el('usb-log').textContent='';try{const d=await enumerateSTMUSB(send,log);address=d.address;el('usb-state').textContent='Aygıt tanındı · adres 7 · EP1';}catch(e){if(el('usb-state'))el('usb-state').textContent=e.message;}finally{busy(false);}};
 el('usb-echo').onclick=async()=>{const bytes=new TextEncoder().encode(el('usb-payload').value);busy(true);try{const all=[];for(let at=0;at<Math.max(bytes.length,1);at+=64){const part=[...bytes.slice(at,at+64)],out=await send('out',{address,endpoint:1,data:part});if(out.status!=='ACK')throw Error('OUT '+out.status);log('OUT '+hex(part));let input;for(let n=0;n<20;n++){input=await send('in',{address,endpoint:1});if(input.status!=='NAK')break;}if(input.status!=='ACK')throw Error('IN '+input.status);log('IN  '+hex(input.data));all.push(...input.data);}const equal=all.length===bytes.length&&all.every((v,i)=>v===bytes[i]);el('usb-state').textContent=(equal?'Echo doğrulandı':'Farklı firmware yanıtı')+' · '+all.length+' bayt · '+new TextDecoder().decode(Uint8Array.from(all));}catch(e){if(el('usb-state'))el('usb-state').textContent=e.message;}finally{busy(false);}};
}
